local scope = Instance.new("Frame")
scope.Name, scope.LayoutOrder, scope.Size = "Scope", 2, UDim2.fromOffset(220, 220)
scope.BackgroundColor3, scope.BorderSizePixel = THEME.scope, 0
scope.ClipsDescendants = true
