local function ringLabel(text, mi)
	local t = Instance.new("TextLabel")
	t.AnchorPoint = Vector2.new(0, 1)
	t.Position = UDim2.fromScale(0.5 + 0.02, 0.5 - mi / RANGE_MI / 2 + 0.005)
