brand.TextXAlignment, brand.Text = Enum.TextXAlignment.Left, "OMNIRISK  ·  SIM CONTROL"
brand.Parent = header
local collapsed = false
local collapseBtn
collapseBtn = chip(header, "–", 0, function()
	collapsed = not collapsed
