section("INSTANT")
local INSTANT = {
	{ "strike8", "Strike 8 mi W" }, { "strike6", "Strike 6 mi W" }, { "strike15", "Strike 15 mi W" },
	{ "heat", "Heat 115°F" }, { "flood", "Downpour + flood" }, { "wind", "High wind 45" },
