local function playerOf(part)
	local node = part
	while node and node ~= workspace do
		if node:IsA("Model") and node:FindFirstChildOfClass("Humanoid") then
			return Players:GetPlayerFromCharacter(node)
		end
		node = node.Parent
	end
	return nil
end

