		zoneLine.Text, zoneLine.TextColor3 = "STOP WORK, LEAVE THE WORK ZONE", RED
		hintLine.Text = "Lightning inside 10 miles. Get to a truck until the 30 minute all clear."
		stroke.Color = RED
