		stroke.Color = GREEN
	else
		zoneLine.Text, zoneLine.TextColor3 = "OUTSIDE THE WORK ZONE", AMBER
		hintLine.Text = "Walk into the striped work zone by the beacon to check in on the muster list."
		stroke.Color = stop and RED or AMBER
	end
end

while true do
	render()
	task.wait(0.25)
end
